namespace enx_fit.ViewModels;

public sealed record PublicFaq(string Id, string Question, string Answer)
{
    public static IReadOnlyList<PublicFaq> All { get; } = [
        new("faq-install", "Нужно устанавливать приложение?", "Enix Fit работает в браузере на телефоне и компьютере. На телефоне сайт можно добавить на главный экран через меню браузера. История привязана к вашему аккаунту."),
        new("faq-start", "Можно начать без программы?", "Да. Начните свободную тренировку и добавляйте упражнения по ходу. Если занятие уже прошло, внесите его вручную. Тренировку с выполненными подходами можно сохранить как шаблон."),
        new("faq-free", "Что входит в бесплатный план?", "Свои программы без лимита, готовые шаблоны, расписание, запись подходов, таймер отдыха, история, личные рекорды, графики и замеры тела. Вес и повторения можно менять вручную."),
        new("faq-access", "Как получить Pro или Coach?", "Онлайн-оплата пока недоступна. Эти планы назначает администратор. Coach дополнительно требует роль тренера. Текущий доступ показан в профиле на странице планов."),
        new("faq-offline", "Что происходит при потере сети?", "В уже открытом занятии записи подходов могут ожидать отправки. Следите за состоянием сохранения и восстановите соединение, чтобы синхронизировать результат. Формы замеров и настроек сохраняют введённые значения в открытой вкладке и предлагают повторить отправку. Полный запуск и все действия без сети пока не поддерживаются."),
        new("faq-progress", "Из чего строятся графики прогресса?", "По завершённым тренировкам и выполненным рабочим подходам. Разминка, пропущенные подходы и незавершённые занятия не увеличивают результат. Замеры тела строятся по отдельным сохранённым записям."),
        new("faq-schedule", "Можно перенести одно занятие?", "Да. В календаре программы можно перенести конкретное занятие. Остальное расписание сохраняется. Плановые веса и повторы отделены от выполненных результатов."),
        new("faq-data", "Где исправить запись или скачать историю?", "Замеры можно изменить и удалить в разделе прогресса, записанную тренировку — через историю занятий. Выгрузка тренировок в CSV и JSON доступна в профиле. Настройки аккаунта содержат выгрузку личных данных."),
        new("faq-recovery", "Что делать, если не получается войти?", "Проверьте email и пароль; при включённой двухэтапной проверке нужен код или код восстановления. Отправка писем для сброса пароля пока не подключена. Страница восстановления сообщает о доступности этого способа."),
        new("faq-trainer", "Какие данные видит тренер?", "Тренер работает с назначенными ему клиентами: просматривает их тренировки и программы, назначает копии программ и меняет нагрузку. Клиентский режим отмечен в интерфейсе; личные настройки аккаунта относятся к самому тренеру.")
    ];

    public static IReadOnlyList<PublicFaq> Find(string? search)
    {
        if (string.IsNullOrWhiteSpace(search)) return All;
        var words = Normalize(search).Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        return All.Where(item => words.All(word => Normalize(item.Question + " " + item.Answer).Contains(word, StringComparison.Ordinal))).ToList();
    }
    private static string Normalize(string text) => text.ToLowerInvariant().Replace('ё', 'е');
}
